t = int(input())
for i in range(t):
	nums = input().split(' ')
	(n, k, s, l) = (int(nums[0]), int(nums[1]), int(nums[2]), [])
	for j in range(n):
		l.append(k ** j)
	(total, l_good, a) = (s, [], 0)
	for x in range(1, len(l) + 1):
		if total - l[-x] >= 0:
			l_good.append((-1) ** a)
			total -= l[-x]
		elif x != len(l) and total - l[-x] < 0 and (abs(total - l[-x]) <= sum(l[-len(l):-x])):
			l_good.append((-1) ** a)
			a += 1
			total = l[-x] - total
		else:
			l_good.append(0)
	if total == 0:
		for y in range(n):
			print(l_good[::-1][y], end=' ')
		print()
	else:
		print(-2)
